import { useEffect, useState } from "react";
import { fetchTags } from "../services/tagsApi";

const INITIAL_STATE = {
  tags: [],
  loading: true,
  error: "",
};

function isCanceledError(requestError) {
  return (
    requestError?.name === "CanceledError" ||
    requestError?.code === "ERR_CANCELED"
  );
}

function usePopularTags(fetchTagsFn = fetchTags) {
  const [state, setState] = useState(INITIAL_STATE);

  useEffect(() => {
    const controller = new AbortController();

    async function loadTags() {
      setState((previousState) => ({
        ...previousState,
        loading: true,
        error: "",
      }));

      try {
        const nextTags = await fetchTagsFn(controller.signal);
        setState({
          tags: nextTags,
          loading: false,
          error: "",
        });
      } catch (requestError) {
        if (!isCanceledError(requestError)) {
          setState({
            tags: [],
            loading: false,
            error: "Tags list not available",
          });
          console.error(requestError);
        }
      }
    }

    loadTags();

    return () => {
      controller.abort();
    };
  }, [fetchTagsFn]);

  return state;
}

export default usePopularTags;

import usePopularTags from "../../hooks/usePopularTags";

function renderTags(tags, maxTags) {
  return (
    <ul className="tag-list-items">
      {tags.slice(0, maxTags).map((name) => (
        <li key={name}>
          <button className="tag-pill tag-default" type="button">
            {name}
          </button>
        </li>
      ))}
    </ul>
  );
}

function getContent({ tags, loading, error, maxTags }) {
  if (loading) {
    return <p>Loading tags...</p>;
  }

  if (error) {
    return <p>{error}</p>;
  }

  if (tags.length > 0) {
    return renderTags(tags, maxTags);
  }

  return <p>Tags list not available</p>;
}

function PopularTags({ maxTags = 50 }) {
  const { tags, loading, error } = usePopularTags();

  return (
    <aside className="col-md-3">
      <div className="sidebar">
        <h6>Popular Tags</h6>
        <div className="tag-list">
          {getContent({ tags, loading, error, maxTags })}
        </div>
      </div>
    </aside>
  );
}

export default PopularTags;

